const range = editor.getSelectedLineRange();
const text = editor.getTextInRange(range[0], range[1]);
if (!text.trim()) { context.fail('Select lines to sort.'); }
else {
  const choice = SelectPrompt.create(); choice.title = 'Sort lines';
  choice.addItem('asc', 'Ascending'); choice.addItem('desc', 'Descending');
  if (!choice.show()) { context.cancel(); }
  else {
    const newline = text.endsWith('\n');
    const lines = (newline ? text.slice(0, -1) : text).split('\n');
    lines.sort((a, b) => a.localeCompare(b));
    if (choice.selectedItem.id === 'desc') lines.reverse();
    editor.setTextInRange(range[0], range[1], lines.join('\n') + (newline ? '\n' : ''));
  }
}
